INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (95193,0,0,'Ah, $n. So the Lich King chose you to be his hand? I\'m not surprised. We have all heard of your exploits.',12,0,100.0,0,0,61923,96959,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (95193,1,0,'Our forces have gathered from all across Northrend. When the call to action comes... and it will come soon... the Knights of the Ebon Blade will be ready.',12,0,100.0,0,0,61924,96960,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (95193,2,0,'Make no mistake, we are not bound to this new Lich King. However, he may prove a valuable ally against the Legion.',12,0,100.0,0,0,61925,96961,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (95193,3,0,'For now, our goals align with his. And in the meantime, it is in our best interests that the Scourge stay... contained.',12,0,100.0,0,0,61926,96964,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (95193,4,0,'The gates of Icecrown lie to the north. Do not keep our ally waiting!',12,0,100.0,1,0,61927,96962,0,'LegionCore');
