INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102561,0,0,'<cough> Spare me your paltry words, Sliver. I\'ve not taken my final breath yet!',12,0,100.0,0,0,0,105016,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102561,1,0,'These cursed demons are going to learn a new meaning of suffering when I get free! A beast called Zalinor carries the keystone that unlocks these bindings. Set me free and I\'ll help you rip the bastards apart!',12,0,100.0,0,0,0,105042,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102561,2,0,'Ah! That\'s much better!',12,0,100.0,0,0,0,105089,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102561,3,0,'We don\'t have much time! Margrave was taken to the citadel. The only things I\'ve seen come out of that place are demons and corpses! We\'ll need to break in there to get him out.',12,0,100.0,0,0,0,105090,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102561,4,0,'What!? Don\'t you have any sense of duty to aid your fellow knights?',12,0,100.0,0,0,0,105303,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102561,5,0,'You\'re a cold one, Sliver. Fine! I\'ll help, but if we have any chance of getting Margrave out alive, we should take it.',12,0,100.0,0,0,0,105325,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102561,6,0,'The Legion took my weapons from me, so it\'s only fitting that I take one of theirs.',12,0,100.0,0,0,0,105182,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102561,7,0,'What\'s the delay? Go already!',12,0,100.0,0,0,0,105284,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102561,8,0,'Owwww!!! Owwww!!',12,0,100.0,0,0,0,105239,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102561,9,0,'More incoming! Intercept them!',14,0,100.0,0,0,0,105293,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102561,10,0,'Poor Margrave! The final death claimed you at last.',12,0,100.0,0,0,0,105372,0,'LegionCore');
